use merge_sort::merge_sort;

#[test]
fn test_basic() {
    let mut v = vec![5, 2, 8, 1, 9, 3];
    merge_sort(&mut v);
    assert_eq!(v, vec![1, 2, 3, 5, 8, 9]);
}

#[test]
fn test_already_sorted() {
    let mut v = vec![1, 2, 3];
    merge_sort(&mut v);
    assert_eq!(v, vec![1, 2, 3]);
}

#[test]
fn test_reverse() {
    let mut v = vec![5, 4, 3, 2, 1];
    merge_sort(&mut v);
    assert_eq!(v, vec![1, 2, 3, 4, 5]);
}

#[test]
fn test_empty() {
    let mut v: Vec<i32> = vec![];
    merge_sort(&mut v);
    assert_eq!(v, vec![]);
}

#[test]
fn test_duplicates() {
    let mut v = vec![3, 1, 4, 1, 5, 9, 2, 6, 5];
    merge_sort(&mut v);
    assert_eq!(v, vec![1, 1, 2, 3, 4, 5, 5, 6, 9]);
}
